 "content": "def transform(grid):
    # Repeated hollow-corner motif with a one-cell gap at the upper right:
    # fill its interior and extend a blue arm in the direction of the opening.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    for r in range(h - 3):
        for c in range(w - 3):
            # 4x4 motif: left and bottom edges complete; top has missing c+2,
            # right edge at c+3. This is the observed open corner pattern.
            if (g[r][c] == 5 and g[r][c+1] == 5 and g[r][c+2] == 0 and
                g[r][c+3] == 5 and
                all(g[rr][c] == 5 and g[rr][c+3] == 5 for rr in range(r+1,r+3)) and
                all(g[r+3][cc] == 5 for cc in range(c,c+4)) and
                all(g[rr][cc] == 0 for rr in range(r+1,r+3) for cc in (c+1,c+2))):
                for rr in range(r+1,r+3):
                    for cc in range(c+1,c+3):
                        g[rr][cc] = 2
                # Extend from the missing top cell to the left edge.
                for cc in range(max(0,c-1), c+3):
                    if g[r-1][cc] == 0 if r > 0 else False:
                        g[r-1][cc] = 2
    return g

